const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry and dates
  const centerPoint = ee.Geometry.Point([-116.939238, 50.332360]);
  const roi = centerPoint.buffer(60000); // 60 km radius

  const date1Start = '2020-12-02';
  const date1End = '2020-12-03';
  const date2Start = '2020-12-05';
  const date2End = '2020-12-06';

  // 2. Get Sentinel-2 images for both dates
  const s2_dec2 = ee.ImageCollection('COPERNICUS/S2_CLOUD_PROBABILITY')
    .filterBounds(roi)
    .filterDate(date1Start, date1End);

  const s2_dec5 = ee.ImageCollection('COPERNICUS/S2_CLOUD_PROBABILITY')
    .filterBounds(roi)
    .filterDate(date2Start, date2End);

  const size_dec2 = await s2_dec2.size().getInfo();
  const size_dec5 = await s2_dec5.size().getInfo();

  console.log(`Dec 2 Images: ${size_dec2}`);
  console.log(`Dec 5 Images: ${size_dec5}`);

  // Check if collections are empty
  if (size_dec2 === 0 || size_dec5 === 0) {
    console.log("Missing data for one or both dates.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Process images - mosaic if multiple images per date
  const img_dec2 = s2_dec2.mosaic();
  const img_dec5 = s2_dec5.mosaic();

  // 4. Calculate cloud statistics
  // Cloud probability > 50 means cloudy pixel
  const cloudThreshold = 50;
  const cloudMask_dec2 = img_dec2.select('probability').gt(cloudThreshold);
  const cloudMask_dec5 = img_dec5.select('probability').gt(cloudThreshold);

  // Count total pixels and cloudy pixels
  const stats_dec2 = await cloudMask_dec2.reduceRegion({
    reducer: ee.Reducer.sum().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const stats_dec5 = await cloudMask_dec5.reduceRegion({
    reducer: ee.Reducer.sum().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const cloudPixels_dec2 = stats_dec2['probability_sum'];
  const totalPixels_dec2 = stats_dec2['probability_count'];
  const cloudPixels_dec5 = stats_dec5['probability_sum'];
  const totalPixels_dec5 = stats_dec5['probability_count'];

  // 5. Validation
  if (totalPixels_dec2 === 0 || totalPixels_dec5 === 0) {
    console.log("No valid pixels found.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (cloudPixels_dec2 === null || cloudPixels_dec5 === null || 
      totalPixels_dec2 === null || totalPixels_dec5 === null) {
    console.log("Calculation failed.");
    console.log("<answer>C3</answer>");
    return;
  }

  const cloudPercent_dec2 = (cloudPixels_dec2 / totalPixels_dec2) * 100;
  const cloudPercent_dec5 = (cloudPixels_dec5 / totalPixels_dec5) * 100;

  console.log(`Dec 2: ${cloudPercent_dec2.toFixed(2)}% cloud cover (${totalPixels_dec2} pixels)`);
  console.log(`Dec 5: ${cloudPercent_dec5.toFixed(2)}% cloud cover (${totalPixels_dec5} pixels)`);
  console.log(`Change: ${(cloudPercent_dec5 - cloudPercent_dec2).toFixed(2)}%`);

  // 6. Final answer
  if (cloudPercent_dec5 > cloudPercent_dec2) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
